cat > /tmp/stage34.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE VIEW FM AS SELECT * FROM read_parquet('/workspace/work/field_match.parquet');
CREATE VIEW M AS SELECT * FROM FM WHERE pass_single OR pass_agg;
.mode box
-- q11
SELECT min(max_single_frac) min_single, avg(max_single_frac) avg_single, avg(union_frac) avg_union FROM M;
-- q12: fields intersecting a listed parcel (positive area) but failing both tests
SELECT count(*) n_excluded FROM FM WHERE max_single_frac>0 AND NOT (pass_single OR pass_agg);
-- q14
SELECT sum(area_ha) matched_field_ha FROM M;
-- q15 pieces
SELECT count(*) n_fields, sum(area_ha) mha, sum(d5)/10000.0 post2020, sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) nloss FROM M;
-- distinct mb classes on matched fields
SELECT mbmode24, count(*) n, sum(area_ha) ha FROM M GROUP BY 1 ORDER BY 3 DESC;
EOF
