.mode box
SELECT mbmode24, count(*) n_all, sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) n_loss,
  sum(area_ha) area_ha, sum(d5)/10000.0 post2020_ha,
  sum(CASE WHEN d5>0 THEN area_ha ELSE 0 END) area_with_loss
FROM M GROUP BY 1 ORDER BY 1;
-- era band totals across matched fields
SELECT sum(d1)/10000 e1, sum(d2)/10000 e2, sum(d3)/10000 e3, sum(d4)/10000 e4, sum(d5)/10000 e5 FROM M;
