cat > /tmp/year.sql <<'EOF'
INSTALL spatial; LOAD spatial;
CREATE VIEW M AS SELECT * FROM read_parquet('/workspace/work/field_match.parquet') WHERE pass_single OR pass_agg;
CREATE VIEW rawf AS SELECT * FROM read_parquet('/workspace/work/fields.parquet');
.mode box
-- inspect mode_year etc on matched fields with any loss
SELECT r.mode_year, r.firstyear, r.firstyearmajority, count(*) n
FROM M JOIN rawf r ON M.Id=r.Id
WHERE (M.d1+M.d2+M.d3+M.d4+M.d5)>0
GROUP BY 1,2,3 ORDER BY n DESC LIMIT 15;
EOF
