cat > /tmp/dom.sql <<'EOF'
INSTALL spatial; LOAD spatial;
CREATE VIEW MF AS SELECT * FROM read_parquet('/workspace/work/mf.parquet');
CREATE VIEW FLAG AS SELECT DISTINCT primary_cod FROM MF WHERE in_scope AND d5>0;
-- dominant class per flagged parcel: most ha among all matched fields on parcel, tie lowest code
CREATE VIEW DOM AS
WITH agg AS (
  SELECT primary_cod, mbmode24, sum(area_ha) ha
  FROM MF WHERE primary_cod IN (SELECT primary_cod FROM FLAG)
  GROUP BY 1,2),
r AS (SELECT *, row_number() OVER (PARTITION BY primary_cod ORDER BY ha DESC, mbmode24 ASC) rn FROM agg)
SELECT primary_cod, mbmode24 dominant_mb FROM r WHERE rn=1;
.mode box
SELECT dominant_mb, count(*) n FROM DOM GROUP BY 1 ORDER BY 1;
EOF
