cat > /tmp/flagdet.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
CREATE VIEW MF AS SELECT * FROM read_parquet('/workspace/work/mf.parquet');
CREATE VIEW FLAG AS SELECT DISTINCT primary_cod FROM MF WHERE in_scope AND d5>0;
CREATE VIEW DOM AS
WITH agg AS (SELECT primary_cod, mbmode24, sum(area_ha) ha FROM MF WHERE primary_cod IN (SELECT primary_cod FROM FLAG) GROUP BY 1,2),
r AS (SELECT *, row_number() OVER (PARTITION BY primary_cod ORDER BY ha DESC, mbmode24 ASC) rn FROM agg)
SELECT primary_cod, mbmode24 dominant_mb FROM r WHERE rn=1;
-- build flagged parcel table with centroid (5880) and muni_code
CREATE TABLE FP AS
SELECT p.cod_imovel, split_part(p.cod_imovel,'-',2) muni_code, p.municipio,
  d.dominant_mb,
  ST_Centroid(p.geometry) cen4326,
  ST_Transform(ST_Centroid(p.geometry),'EPSG:4326','EPSG:5880') cen5880
FROM read_parquet('/workspace/work/parcels.parquet') p JOIN DOM d ON p.cod_imovel=d.primary_cod;
COPY FP TO '/workspace/work/flagged.parquet' (FORMAT parquet);
.mode box
SELECT muni_code, dominant_mb, count(*) n FROM FP GROUP BY 1,2 ORDER BY 1,2;
SELECT DISTINCT muni_code FROM FP;
EOF
