cat > /tmp/final.sql <<'EOF'
INSTALL spatial; LOAD spatial;
SET geometry_always_xy = true;
PRAGMA threads=4;

CREATE VIEW MF AS SELECT * FROM read_parquet('/workspace/work/mf.parquet');
CREATE VIEW FMALL AS SELECT * FROM read_parquet('/workspace/work/field_match.parquet');
CREATE VIEW M AS SELECT * FROM FMALL WHERE pass_single OR pass_agg;
CREATE VIEW RANKED AS SELECT * FROM read_parquet('/workspace/work/ranked.parquet');
CREATE VIEW FLAGP AS SELECT * FROM read_parquet('/workspace/work/flagged.parquet');
CREATE VIEW RAWF AS SELECT Id, mode_year FROM read_parquet('/workspace/work/fields.parquet');
CREATE VIEW PARCELS AS SELECT cod_imovel, municipio FROM read_parquet('/workspace/work/parcels.parquet');

-- flagged parcel commodity + per-parcel in-scope post2020 loss
CREATE TABLE FPX AS
SELECT f.cod_imovel, f.dominant_mb, f.muni_code, p.municipio muni_name,
  CASE WHEN f.dominant_mb IN (15,21) THEN 'cattle' WHEN f.dominant_mb=39 THEN 'soya' END commodity,
  CASE WHEN f.dominant_mb IN (15,21) THEN 'slaughter_point'
       WHEN f.dominant_mb=39 THEN 'gravity_catchment|intake_point' END routed_tier,
  COALESCE((SELECT sum(m.d5)/10000.0 FROM MF m WHERE m.primary_cod=f.cod_imovel AND m.in_scope),0.0) post2020_loss_ha
FROM FLAGP f JOIN PARCELS p ON f.cod_imovel=p.cod_imovel;

------ STAGE 1
COPY (SELECT 3 AS n_collections, 'trazo3-fields' AS recommended_id) TO '/workspace/answers/q01.csv' (HEADER);
COPY (SELECT * FROM (VALUES
  ('gravity_catchment',3103),('intake_point',18796),('membership_muni',5257),('mill_point',417),('slaughter_point',13096))
  t(tier,n) ORDER BY tier) TO '/workspace/answers/q02.csv' (HEADER);
COPY (SELECT 8453552 AS n_rows, 8437938 AS n_distinct_ids) TO '/workspace/answers/q03.csv' (HEADER);
COPY (SELECT 772404 AS n_rows, 4326 AS epsg) TO '/workspace/answers/q04.csv' (HEADER);

------ STAGE 2
COPY (SELECT 117 AS list_ids, 117 AS found_in_car, 0 AS missing) TO '/workspace/answers/q05.csv' (HEADER);
COPY (SELECT municipio, count(*) AS n_parcels FROM PARCELS GROUP BY 1 ORDER BY municipio) TO '/workspace/answers/q06.csv' (HEADER);
COPY (SELECT 0 AS n_duplicate_ids, 0 AS n_parcels_under_1ha) TO '/workspace/answers/q07.csv' (HEADER);
COPY (SELECT 119 AS input_rows, 114 AS resolved_clean, 1 AS centroid_resolved, 1 AS geometry_resolved,
  1 AS axis_repaired, 1 AS duplicates_removed, 1 AS unresolvable) TO '/workspace/answers/q31.csv' (HEADER);

------ STAGE 3
COPY (SELECT 3291 AS n_fields_in_envelope) TO '/workspace/answers/q08.csv' (HEADER);
COPY (SELECT count(*) AS matched_fields FROM M) TO '/workspace/answers/q09.csv' (HEADER);
COPY (SELECT sum(CASE WHEN pass_single THEN 1 ELSE 0 END) AS by_single_parcel_rule,
             sum(CASE WHEN pass_agg AND NOT pass_single THEN 1 ELSE 0 END) AS by_aggregate_rule_only
      FROM M) TO '/workspace/answers/q10.csv' (HEADER);
COPY (SELECT min(max_single_frac) AS min_single_frac, avg(max_single_frac) AS avg_single_frac,
             avg(union_frac) AS avg_union_frac FROM M) TO '/workspace/answers/q11.csv' (HEADER);
COPY (SELECT count(*) AS n_excluded FROM FMALL WHERE max_single_frac>0 AND NOT (pass_single OR pass_agg))
  TO '/workspace/answers/q12.csv' (HEADER);
COPY (SELECT primary_cod AS cod_imovel, count(*) AS n_fields FROM MF GROUP BY 1
      ORDER BY n_fields DESC, cod_imovel ASC LIMIT 10) TO '/workspace/answers/q13.csv' (HEADER);
COPY (SELECT sum(area_ha) AS matched_field_ha FROM M) TO '/workspace/answers/q14.csv' (HEADER);

------ STAGE 4
COPY (SELECT 117 AS n_parcels, count(*) AS n_fields, sum(area_ha) AS matched_field_ha,
   sum(d5)/10000.0 AS post2020_loss_ha, sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) AS fields_with_post2020_loss
   FROM M) TO '/workspace/answers/q15.csv' (HEADER);
COPY (SELECT DISTINCT mbmode24, mb_class, commodity AS annex1_commodity, in_scope, caveat
      FROM MF ORDER BY mbmode24) TO '/workspace/answers/q16.csv' (HEADER);
COPY (SELECT commodity AS annex1_commodity, sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) AS n_fields,
      sum(d5)/10000.0 AS post2020_loss_ha FROM MF WHERE in_scope GROUP BY 1 ORDER BY 1)
      TO '/workspace/answers/q17.csv' (HEADER);
COPY (SELECT mb_class, sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) AS n_fields, sum(d5)/10000.0 AS post2020_loss_ha
      FROM MF WHERE NOT in_scope AND d5>0 GROUP BY 1 ORDER BY 1) TO '/workspace/answers/q18.csv' (HEADER);
COPY (SELECT commodity AS annex1_commodity, sum(area_ha) AS total_ha,
      sum(CASE WHEN d5>0 THEN area_ha ELSE 0 END)/sum(area_ha) AS loss_share
      FROM MF WHERE in_scope GROUP BY 1 ORDER BY 1) TO '/workspace/answers/q19.csv' (HEADER);
COPY (SELECT primary_cod AS cod_imovel, any_value(muni_name) AS municipio, sum(d5)/10000.0 AS post2020_loss_ha,
      sum(CASE WHEN d5>0 THEN 1 ELSE 0 END) AS n_fields_post2020_loss
      FROM MF WHERE in_scope GROUP BY 1 HAVING sum(d5)>0
      ORDER BY post2020_loss_ha DESC, cod_imovel ASC LIMIT 10) TO '/workspace/answers/q20.csv' (HEADER);
COPY (WITH e AS (SELECT unnest(['2001-2004','2005-2009','2010-2014','2015-2020','2021-2024']) era,
        unnest([sum(d1),sum(d2),sum(d3),sum(d4),sum(d5)])/10000.0 cleared_ha FROM M)
      SELECT era, cleared_ha, 100.0*cleared_ha/sum(cleared_ha) OVER () AS pct_of_loss FROM e ORDER BY era)
      TO '/workspace/answers/q21.csv' (HEADER);
COPY (SELECT CAST(r.mode_year AS INTEGER) AS loss_year, count(*) AS n_fields, sum(m.total_loss_ha) AS cleared_ha
      FROM MF m JOIN RAWF r ON m.Id=r.Id WHERE m.total_loss_ha>0
      GROUP BY 1 ORDER BY loss_year) TO '/workspace/answers/q22.csv' (HEADER);
COPY (SELECT Id AS field_id, primary_cod AS cod_imovel, commodity AS annex1_commodity,
      area_ha AS field_area_ha, post2020_ha AS post2020_loss_ha
      FROM MF WHERE in_scope ORDER BY post2020_ha DESC, field_id ASC LIMIT 10) TO '/workspace/answers/q23.csv' (HEADER);

------ STAGE 5
COPY (SELECT cod_imovel, dominant_mb, commodity AS annex1_commodity, routed_tier FROM FPX ORDER BY cod_imovel)
  TO '/workspace/answers/q24.csv' (HEADER);
COPY (SELECT * FROM (VALUES ('cattle','slaughter_point','covered'),('soya','intake_point','covered'))
  t(annex1_commodity,tier,coverage) ORDER BY annex1_commodity) TO '/workspace/answers/q25.csv' (HEADER);
COPY (WITH d AS (SELECT cod_imovel, entity_id, tier, dist_km,
        row_number() OVER (PARTITION BY cod_imovel ORDER BY dist_km ASC, entity_id ASC) rn
        FROM RANKED WHERE cat='delivery')
      SELECT cod_imovel, entity_id, tier, dist_km AS distance_km FROM d WHERE rn=1 ORDER BY cod_imovel)
      TO '/workspace/answers/q26.csv' (HEADER);
COPY (SELECT cod_imovel, entity_id, evidence FROM RANKED WHERE cat='relationship' ORDER BY cod_imovel)
      TO '/workspace/answers/q27.csv' (HEADER);
COPY (SELECT cod_imovel,
        sum(CASE WHEN rn<=5 THEN 1 ELSE 0 END) AS total_candidates,
        sum(CASE WHEN rn<=5 AND cat='relationship' THEN 1 ELSE 0 END) AS relationship_candidates,
        sum(CASE WHEN rn<=5 AND cat='delivery' THEN 1 ELSE 0 END) AS delivery_candidates,
        0 AS widened, 0 AS no_match,
        max(CASE WHEN nbf THEN 1 ELSE 0 END) AS nearest_by_far
      FROM RANKED GROUP BY 1 ORDER BY cod_imovel) TO '/workspace/answers/q28.csv' (HEADER);
COPY (SELECT 0 AS n_widened, 0 AS n_no_match,
      (SELECT count(DISTINCT cod_imovel) FROM RANKED WHERE nbf) AS n_nearest_by_far) TO '/workspace/answers/q29.csv' (HEADER);

------ STAGE 6
CREATE TABLE TOP AS
SELECT r.cod_imovel, fpx.commodity AS annex1_commodity, fpx.post2020_loss_ha,
   r.entity_id, r.entity_kind, r.tier, r.basis, r.dist_km AS distance_km
FROM RANKED r JOIN FPX fpx ON r.cod_imovel=fpx.cod_imovel WHERE r.rn=1;
COPY (SELECT cod_imovel, annex1_commodity, post2020_loss_ha, entity_id, entity_kind, tier, basis, distance_km
      FROM TOP ORDER BY cod_imovel) TO '/workspace/answers/q30.csv' (HEADER);
COPY (SELECT cod_imovel, annex1_commodity, post2020_loss_ha, entity_id AS top_contact_entity_id,
      entity_kind, tier, basis, distance_km FROM TOP ORDER BY cod_imovel)
      TO '/workspace/answers/workflow.csv' (HEADER);
SELECT 'done' status;
EOF
duckdb < /tmp/final.sql 2>&1 | tail -20
